"}, "is_correct": false}, {"id": "04336fbf-482e-49d8-8e24-b97aa1413b17", "text": {"en": "Dimitar Berbatov", "ka": "დმიტარ ბერბატოვი"}, "is_correct": false}]}, "quiz_slug": "tottenham", "difficulty": "hard", "explanation": null, "category_name": {"en": "Premier League", "ka": "პრემიერ ლიგა"}, "category_slug": "premier-league", "display_order": 15}]$curated$::jsonb) AS seed(
