DELETE FROM public.campaign_quiz_questions
WHERE quiz_slug IN (
  'arsenal', 'chelsea', 'club-badges', 'manchester-city',
  'liverpool', 'manchester-united', 'tottenham', 'everton',
  'premier-league', 'guess-the-player', 'career-path'
);

DELETE FROM public.questions question
USING public.campaign_quiz_manual_questions managed
WHERE question.id = managed.question_id
  AND managed.quiz_slug IN ('arsenal', 'chelsea', 'club-badges', 'manchester-city');

INSERT INTO public.categories (slug, name, is_active)
VALUES
  ('arsenal', '{"en":"Arsenal Quiz"}'::jsonb, TRUE),
  ('chelsea', '{"en":"Chelsea Quiz"}'::jsonb, TRUE),
  ('club-badges', '{"en":"Club Badges Quiz"}'::jsonb, TRUE),
  ('manchester-city', '{"en":"Manchester City Quiz"}'::jsonb, TRUE)
ON CONFLICT (slug) DO UPDATE
SET is_active = TRUE,
    updated_at = NOW();

INSERT INTO public.categories (slug, name, is_active)
SELECT DISTINCT ON (category_slug)
  category_slug,
  category_name,
  TRUE
FROM campaign_quiz_curated_seed
ORDER BY category_slug
ON CONFLICT (slug) DO UPDATE
SET is_active = TRUE,
    updated_at = NOW();

INSERT INTO public.questions (
  id,
  category_id,
  type,
  difficulty,
  status,
  prompt,
  explanation,
  ranked_eligible,
  visibility
)
SELECT
  seed.id,
  category.id,
  seed.type,
  seed.difficulty,
  'published',
  seed.prompt,
  seed.explanation,
  FALSE,
  'public'
FROM campaign_quiz_curated_seed seed
JOIN public.categories category ON category.slug = seed.category_slug
ON CONFLICT (id) DO UPDATE
SET category_id = EXCLUDED.category_id,
    type = EXCLUDED.type,
    difficulty = EXCLUDED.difficulty,
    status = EXCLUDED.status,
    prompt = EXCLUDED.prompt,
    explanation = EXCLUDED.explanation,
    ranked_eligible = FALSE,
    visibility = 'public',
    updated_at = NOW();

INSERT INTO public.question_payloads (question_id, payload)
SELECT id, payload
FROM campaign_quiz_curated_seed
ON CONFLICT (question_id) DO UPDATE
SET payload = EXCLUDED.payload,
    updated_at = NOW();

INSERT INTO public.questions (
  id,
  category_id,
  type,
  difficulty,
  status,
  prompt,
  explanation,
  ranked_eligible,
  visibility
)
SELECT
  seed.id,
  category.id,
  'mcq_single',
  seed.difficulty,
  'published',
  jsonb_build_object('en', seed.prompt),
  CASE
    WHEN seed.explanation IS NULL OR seed.explanation = '' THEN NULL
    ELSE jsonb_build_object('en', seed.explanation)
  END,
  FALSE,
  'public'
FROM campaign_quiz_manual_seed seed
JOIN public.categories category ON category.slug = seed.quiz_slug
ON CONFLICT (id) DO UPDATE
SET category_id = EXCLUDED.category_id,
    type = EXCLUDED.type,
    difficulty = EXCLUDED.difficulty,
    status = EXCLUDED.status,
    prompt = EXCLUDED.prompt,
    explanation = EXCLUDED.explanation,
    ranked_eligible = FALSE,
    visibility = 'public',
    updated_at = NOW();

INSERT INTO public.question_payloads (question_id, payload)
SELECT id, payload
FROM campaign_quiz_manual_seed
ON CONFLICT (question_id) DO UPDATE
SET payload = EXCLUDED.payload,
    updated_at = NOW();

UPDATE public.campaign_quizzes quiz
SET question_source = 'manual',
    question_set_slug = quiz.slug,
    updated_at = NOW()
WHERE quiz.slug IN ('arsenal', 'chelsea', 'club-badges', 'manchester-city');

INSERT INTO public.campaign_quiz_questions (
  quiz_slug,
  question_id,
  difficulty,
  display_order
)
SELECT quiz_slug, id, difficulty, display_order
FROM campaign_quiz_manual_seed
ORDER BY quiz_slug, display_order;

INSERT INTO public.campaign_quiz_manual_questions (question_id, quiz_slug)
SELECT id, quiz_slug
FROM campaign_quiz_manual_seed
ON CONFLICT (question_id) DO UPDATE
SET quiz_slug = EXCLUDED.quiz_slug;

UPDATE public.campaign_quizzes quiz
SET question_source = 'existing',
    question_set_slug = quiz.slug,
    updated_at = NOW()
WHERE quiz.slug IN (
  'liverpool', 'manchester-united', 'tottenham', 'everton',
  'premier-league', 'guess-the-player', 'career-path'
);

INSERT INTO public.campaign_quiz_questions (
  quiz_slug,
  question_id,
  difficulty,
  display_order
)
SELECT quiz_slug, id, difficulty, display_order
FROM campaign_quiz_curated_seed
ORDER BY quiz_slug, display_order;

-- The content migration seeds these 24 launch pages. Publish them only after
-- proving each attached public-only set contains at least ten questions.
UPDATE public.campaign_quizzes quiz
SET status = 'published',
    published_at = COALESCE(quiz.published_at, NOW()),
    scheduled_publish_at = NULL,
    unpublished_at = NULL,
    updated_at = NOW()
WHERE quiz.slug IN (
  'liverpool', 'manchester-united', 'tottenham', 'everton',
  'premier-league', 'guess-the-player', 'career-path', 'club-badges',
  'arsenal', 'aston-villa', 'bournemouth', 'brentford', 'brighton',
  'chelsea', 'coventry-city', 'crystal-palace', 'fulham', 'hull-city',
  'ipswich-town', 'leeds-united', 'manchester-city', 'newcastle-united',
  'nottingham-forest', 'sunderland'
)
  AND (
    SELECT COUNT(*)
    FROM public.campaign_quiz_questions assigned
    JOIN public.questions question ON question.id = assigned.question_id
    WHERE assigned.quiz_slug = quiz.question_set_slug
      AND question.status = 'published'
      AND question.visibility = 'public'
      AND question.ranked_eligible = FALSE
  ) >= 10;

DO $$
DECLARE
  incomplete TEXT;
  bad_mix TEXT;
BEGIN
  SELECT string_agg(quiz.slug, ', ' ORDER BY quiz.slug)
  INTO incomplete
  FROM public.campaign_quizzes quiz
  WHERE quiz.slug IN (
    'liverpool', 'manchester-united', 'tottenham', 'everton',
    'premier-league', 'guess-the-player', 'career-path', 'club-badges',
    'arsenal', 'aston-villa', 'bournemouth', 'brentford', 'brighton',
    'chelsea', 'coventry-city', 'crystal-palace', 'fulham', 'hull-city',
    'ipswich-town', 'leeds-united', 'manchester-city', 'newcastle-united',
    'nottingham-forest', 'sunderland'
  )
    AND quiz.status <> 'published';

  IF incomplete IS NOT NULL THEN
    RAISE EXCEPTION 'Campaign quiz launch pages are not publishable: %', incomplete;
  END IF;

  SELECT string_agg(mix.quiz_slug, ', ' ORDER BY mix.quiz_slug)
  INTO bad_mix
  FROM (
    SELECT seed.quiz_slug
    FROM campaign_quiz_manual_seed seed
    GROUP BY seed.quiz_slug
    HAVING COUNT(*) <> 15
       OR COUNT(*) FILTER (WHERE difficulty = 'easy') <> 5
       OR COUNT(*) FILTER (WHERE difficulty = 'medium') <> 5
       OR COUNT(*) FILTER (WHERE difficulty = 'hard') <> 5
  ) mix;

  IF bad_mix IS NOT NULL THEN
    RAISE EXCEPTION 'Manual campaign question sets do not have a 5/5/5 mix: %', bad_mix;
  END IF;
END $$;
